function getRouterStack(app) {
    if (app && app._router && Array.isArray(app._router.stack)) {
        return app._router.stack;
    }

    if (app && app.router && Array.isArray(app.router.stack)) {
        return app.router.stack;
    }

    throw new Error("Could not find Express router stack.");
}


function inspectRoutes(app) {
    const stack = getRouterStack(app);

    const routes = [];

    for (const layer of stack) {

        // Middleware does not have a route
        if (!layer.route) {
            continue;
        }

        const path = layer.route.path;

        const methods = Object.keys(layer.route.methods)
            .map(method => method.toUpperCase());

        routes.push({
            path,
            methods
        });
    }

    return routes;
}


function printRoutes(app) {
    const routes = inspectRoutes(app);

    console.log("\n╔════════════════════════════════════════╗");
    console.log("║          REGISTERED ROUTES             ║");
    console.log("╚════════════════════════════════════════╝\n");

    if (routes.length === 0) {
        console.log("No routes found.\n");
        return;
    }

    console.log("  #   METHOD       PATH");
    console.log(" ───────────────────────────────────────");

    routes.forEach((route, index) => {
        const method = route.methods.join(", ");

        console.log(
            `  ${String(index + 1).padEnd(3)} ${method.padEnd(12)} ${route.path}`
        );
    });

    console.log("\n ───────────────────────────────────────");
    console.log(`  Total Routes: ${routes.length}\n`);
}


function getStats(app) {
    const routes = inspectRoutes(app);

    const stats = {
        total: routes.length,
        methods: {}
    };

    for (const route of routes) {
        for (const method of route.methods) {

            if (!stats.methods[method]) {
                stats.methods[method] = 0;
            }

            stats.methods[method]++;
        }
    }

    return stats;
}


function findRoute(app, path, method = null) {
    const routes = inspectRoutes(app);

    return routes.filter(route => {
        const pathMatches = route.path === path;

        if (!method) {
            return pathMatches;
        }

        return (
            pathMatches &&
            route.methods.includes(method.toUpperCase())
        );
    });
}


function findDuplicates(app) {
    const routes = inspectRoutes(app);

    const routeMap = {};

    for (const route of routes) {
        for (const method of route.methods) {

            const key = `${method} ${route.path}`;

            if (!routeMap[key]) {
                routeMap[key] = 0;
            }

            routeMap[key]++;
        }
    }

    const duplicates = [];

    for (const key in routeMap) {
        if (routeMap[key] > 1) {
            duplicates.push({
                route: key,
                count: routeMap[key]
            });
        }
    }

    return duplicates;
}


function getMiddlewares(app) {
    const stack = getRouterStack(app);

    const middlewares = [];

    for (const layer of stack) {

        // Global middleware
        if (!layer.route) {
            if (layer.name && layer.name !== "<anonymous>") {
                middlewares.push({
                    type: "global",
                    name: layer.name
                });
            }

            continue;
        }

        // Route-level middleware
        const routePath = layer.route.path;
        const routeStack = layer.route.stack || [];

        // Everything before the final handler is treated as middleware
        for (let i = 0; i < routeStack.length - 1; i++) {
            const routeLayer = routeStack[i];

            if (routeLayer.name && routeLayer.name !== "<anonymous>") {
                middlewares.push({
                    type: "route",
                    route: routePath,
                    name: routeLayer.name
                });
            }
        }
    }

    return middlewares;
}


module.exports = {
    inspectRoutes,
    printRoutes,
    getStats,
    findRoute,
    findDuplicates,
    getMiddlewares
};